 79	        ItemType::Sword => 100,
 80	        ItemType::Amulet => 60,
 81	        ItemType::Staff => 80,
 82	        ItemType::Potion => 40,
 83	        ItemType::Rune | ItemType::Moonstone => COMPONENT_BASE_PREMIUM,
