 91	/// The special base premium MHPCO offers for one building block.
 92	const BLOCK_BASE_PREMIUM: u64 = 60;
 93	
 94	fn alike_group_base_premium(item_type: ItemType, count: usize) -> u64 {
 95	    if count == BLOCK_COMPONENT_COUNT {
 96	        return BLOCK_BASE_PREMIUM;
 97	    }
 98	    count as u64 * base_premium(item_type)
