101	/// Gathers the policy's items into groups of alike items, counting each group.
102	/// MHPCO counts two items as alike when they are of exactly the same item type
103	/// -- a rune and a moonstone are not alike, so they form no building block
104	/// together, and no other attribute of an item bears on the grouping.
105	fn alike_groups(items: &[Item]) -> Vec<(ItemType, usize)> {
106	    let mut groups: Vec<(ItemType, usize)> = Vec::new();
107	    for item in items {
108	        match groups.iter_mut().find(|(alike, _)| *alike == item.item_type) {
109	            Some((_, count)) => *count += 1,
110	            None => groups.push((item.item_type, 1)),
111	        }
112	    }
113	    groups
114	}
