129	/// An amount of money as MHPCO carries it through a calculation: an exact
130	/// fraction of a G, counted in hundredths. The office keeps every intermediate
131	/// amount in this form and rounds only once, when the final premium or payout
132	/// leaves the calculation -- and it rounds in its own favor, so a premium goes
133	/// up to the next whole G.
134	#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Default)]
135	struct Hundredths(u64);
136	
137	impl Hundredths {
138	    const PER_G: u64 = 100;
139	
140	    const ZERO: Self = Self(0);
141	
142	    fn from_whole_g(whole_g: u64) -> Self {
143	        Self(whole_g * Self::PER_G)
144	    }
145	
146	    /// A rate of this amount, quoted as a percentage of it. MHPCO states
147	    /// every modifier this way, and the share stays exact in hundredths:
148	    /// a rate that does not divide the amount evenly is carried as a
149	    /// fraction rather than rounded here.
150	    fn percentage(self, rate: u64) -> Self {
151	        Self(self.0 * rate / PERCENT)
152	    }
153	
154	    /// Rounds up to whole G, as MHPCO does with a premium.
155	    fn rounded_up_to_whole_g(self) -> u64 {
156	        self.0.div_ceil(Self::PER_G)
157	    }
158	
159	    /// Rounds down to whole G, as MHPCO does with a payout.
160	    fn rounded_down_to_whole_g(self) -> u64 {
161	        self.0 / Self::PER_G
162	    }
163	
164	    fn saturating_sub(self, other: Self) -> Self {
165	        Self(self.0.saturating_sub(other.0))
166	    }
167	}
