/// MHPCO keeps this much of every damage event to itself.
const DEDUCTIBLE_G: u64 = 100;

/// From this enchantment level on, MHPCO reimburses only half the damage.
const HALVED_REIMBURSEMENT_LEVEL: u32 = 8;

/// The share of the damage MHPCO reimburses on a highly enchanted item.
const HALVED_REIMBURSEMENT_RATE: u64 = 50;

/// The insured item a damage report refers to. MHPCO settles a damage only
/// against an item its policy actually covers.
fn insured_item_for<'policy>(insured: &'policy [Item], damage: &Damage) -> &'policy Item {
    insured
        .iter()
        .find(|item| item.item_type == damage.item_type)
        .expect("the damaged item is covered by the policy")
}

/// The share of a damage MHPCO reimburses under the clause the damaged item
/// falls under. A highly enchanted item is reimbursed by half; any other item
/// is reimbursed in full.
fn reimbursed_share(item: &Item) -> u64 {
    if item.enchantment >= HALVED_REIMBURSEMENT_LEVEL {
        return HALVED_REIMBURSEMENT_RATE;
    }
    PERCENT
}

/// What MHPCO reimburses for a damage of this amount to this insured item,
/// before the policy cap: the share its clause allows, less the deductible
/// MHPCO keeps of every damage event.
fn damage_reimbursement(item: &Item, amount: u64) -> Hundredths {
    Hundredths::from_whole_g(amount)
        .percentage(reimbursed_share(item))
        .saturating_sub(Hundredths::from_whole_g(DEDUCTIBLE_G))
}

